CREATE TABLE user_profile (     id INTEGER PRIMARY KEY,     username TEXT,     user_type INTEGER NOT NULL,     first_name TEXT,     last_name TEXT,     profile_photo TEXT,     follower_ids TEXT,     following_ids TEXT,     photo_ids TEXT,     favorite_ids TEXT,     interested_ids TEXT,     ticket_ids TEXT,     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME, bio_text TEXT, post_ids TEXT,     FOREIGN KEY (id) REFERENCES login_data(id) );
INSERT INTO "user_profile" ("id","username","user_type","first_name","last_name","profile_photo","follower_ids","following_ids","photo_ids","favorite_ids","interested_ids","ticket_ids","create_date","update_date","bio_text","post_ids") VALUES(1,'qwertyu',1,'Luka','Ivaniadze','users/1/4b3edd2a-54b6-4ade-a363-5b0179849fce.jpg','5,6','5','','','3,4,2',NULL,'2025-08-31T13:35:24.288Z','2026-08-05T14:40:46.705Z','Lukaq','');
CREATE TABLE venue_profile (     id INTEGER PRIMARY KEY,     username TEXT,     user_type INTEGER NOT NULL,     event_ids TEXT,     title TEXT,     address TEXT,     about TEXT,     status TEXT,     photo_ids TEXT,     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME, public_status INTEGER DEFAULT 0, open_hours TEXT DEFAULT 'Mon-Sun: 10AM-10PM', lat_long TEXT,     FOREIGN KEY (id) REFERENCES login_data(id) );
