CREATE TABLE posts (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id INTEGER NOT NULL,     post_text TEXT NOT NULL,     photo_id TEXT,     like_ids TEXT DEFAULT '',     create_date DATETIME DEFAULT CURRENT_TIMESTAMP,     update_date DATETIME DEFAULT CURRENT_TIMESTAMP , location_tag VARCHAR(255));
